create table if not exists public.coach_athlete_links (id uuid primary key default gen_random_uuid(), coach_user_id uuid not null references auth.users(id) on delete cascade, athlete_user_id uuid not null references auth.users(id) on delete cascade, academy_id uuid references public.academies(id) on delete set null, status text not null default 'active' check (status in ('pending','active','suspended','ended')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (coach_user_id, athlete_user_id, academy_id), check (coach_user_id <> athlete_user_id));
create table if not exists public.academy_coach_seats (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id) on delete cascade, coach_user_id uuid not null references auth.users(id) on delete cascade, seat_type text not null check (seat_type in ('included','paid')), activation_fee numeric(10,2) not null default 0, monthly_fee numeric(10,2) not null default 0, status text not null default 'active' check (status in ('active','pending','canceled')), activated_at timestamptz not null default now(), deactivated_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (academy_id, coach_user_id));
create table if not exists public.coach_approval_requests (id uuid primary key default gen_random_uuid(), athlete_user_id uuid not null references auth.users(id) on delete cascade, coach_user_id uuid not null references auth.users(id) on delete cascade, academy_id uuid references public.academies(id) on delete set null, request_type text not null check (request_type in ('belt_change','competition_weight_category')), current_value text, requested_value text not null, athlete_weight_kg numeric(6,2), notes text, status text not null default 'pending' check (status in ('pending','approved','rejected','withdrawn')), reviewed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.taekwondo_belt_history (id uuid primary key default gen_random_uuid(), athlete_user_id uuid not null references auth.users(id) on delete cascade, coach_user_id uuid not null references auth.users(id) on delete restrict, academy_id uuid references public.academies(id) on delete set null, previous_belt text, new_belt text not null, approved_at timestamptz not null default now(), notes text);
create table if not exists public.taekwondo_weight_category_decisions (id uuid primary key default gen_random_uuid(), athlete_user_id uuid not null references auth.users(id) on delete cascade, coach_user_id uuid not null references auth.users(id) on delete restrict, academy_id uuid references public.academies(id) on delete set null, athlete_weight_kg numeric(6,2) not null, category text not null, decided_at timestamptz not null default now(), notes text);
alter table public.profiles add column if not exists competition_weight_category text, add column if not exists competition_weight_category_updated_at timestamptz;
create index if not exists coach_athlete_links_coach_idx on public.coach_athlete_links(coach_user_id,status);
create index if not exists coach_athlete_links_athlete_idx on public.coach_athlete_links(athlete_user_id,status);
create index if not exists academy_coach_seats_academy_idx on public.academy_coach_seats(academy_id,status);
create index if not exists coach_approval_requests_coach_idx on public.coach_approval_requests(coach_user_id,status,created_at desc);
create index if not exists coach_approval_requests_athlete_idx on public.coach_approval_requests(athlete_user_id,status);
create schema if not exists private;
create or replace function private.user_is_academy_staff(p_academy_id uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.academy_memberships m where m.academy_id=p_academy_id and m.user_id=(select auth.uid()) and m.status='active' and m.role in ('coach','academy_admin')); $$;
create or replace function private.user_is_academy_admin(p_academy_id uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.academy_memberships m where m.academy_id=p_academy_id and m.user_id=(select auth.uid()) and m.status='active' and m.role='academy_admin'); $$;
create or replace function private.user_can_manage_athlete(p_athlete_user_id uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.coach_athlete_links l where l.coach_user_id=(select auth.uid()) and l.athlete_user_id=p_athlete_user_id and l.status='active') or exists(select 1 from public.profiles p join public.academy_memberships coach_m on coach_m.academy_id=p.academy_id and coach_m.user_id=(select auth.uid()) and coach_m.status='active' and coach_m.role in ('coach','academy_admin') join public.academy_memberships athlete_m on athlete_m.academy_id=p.academy_id and athlete_m.user_id=p_athlete_user_id and athlete_m.status='active' and athlete_m.role='athlete'); $$;
alter table public.coach_athlete_links enable row level security; alter table public.academy_coach_seats enable row level security; alter table public.coach_approval_requests enable row level security; alter table public.taekwondo_belt_history enable row level security; alter table public.taekwondo_weight_category_decisions enable row level security;
revoke all on public.coach_athlete_links,public.academy_coach_seats,public.coach_approval_requests,public.taekwondo_belt_history,public.taekwondo_weight_category_decisions from anon;
grant select,insert,update,delete on public.coach_athlete_links,public.academy_coach_seats,public.coach_approval_requests to authenticated; grant select,insert on public.taekwondo_belt_history,public.taekwondo_weight_category_decisions to authenticated;
create policy "coach links participants can view" on public.coach_athlete_links for select to authenticated using ((select auth.uid())=coach_user_id or (select auth.uid())=athlete_user_id or (academy_id is not null and (select private.user_is_academy_staff(academy_id))));
create policy "coach links coaches can create" on public.coach_athlete_links for insert to authenticated with check ((select auth.uid())=coach_user_id and status='active');
create policy "coach links coaches can update" on public.coach_athlete_links for update to authenticated using ((select auth.uid())=coach_user_id or (academy_id is not null and (select private.user_is_academy_admin(academy_id)))) with check ((select auth.uid())=coach_user_id or (academy_id is not null and (select private.user_is_academy_admin(academy_id))));
create policy "coach links coaches can delete" on public.coach_athlete_links for delete to authenticated using ((select auth.uid())=coach_user_id or (academy_id is not null and (select private.user_is_academy_admin(academy_id))));
create policy "academy staff can view seats" on public.academy_coach_seats for select to authenticated using ((select private.user_is_academy_staff(academy_id)) or coach_user_id=(select auth.uid()));
create policy "academy admins can manage seats" on public.academy_coach_seats for all to authenticated using ((select private.user_is_academy_admin(academy_id))) with check ((select private.user_is_academy_admin(academy_id)));
create policy "approval participants can view" on public.coach_approval_requests for select to authenticated using ((select auth.uid())=athlete_user_id or (select auth.uid())=coach_user_id or (academy_id is not null and (select private.user_is_academy_staff(academy_id))));
create policy "athletes can request approval" on public.coach_approval_requests for insert to authenticated with check ((select auth.uid())=athlete_user_id);
create policy "coaches can review approvals" on public.coach_approval_requests for update to authenticated using ((select auth.uid())=coach_user_id and status='pending') with check ((select auth.uid())=coach_user_id);
create policy "belt history participants can view" on public.taekwondo_belt_history for select to authenticated using ((select auth.uid()) in (athlete_user_id,coach_user_id) or (academy_id is not null and (select private.user_is_academy_staff(academy_id))));
create policy "weight decisions participants can view" on public.taekwondo_weight_category_decisions for select to authenticated using ((select auth.uid()) in (athlete_user_id,coach_user_id) or (academy_id is not null and (select private.user_is_academy_staff(academy_id))));
create policy "coach access to linked athlete profiles" on public.profiles for select to authenticated using ((select private.user_can_manage_athlete(user_id)));
